import { test, expect } from '@playwright/test';

test.describe('Sidebar Collapse and Expand', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
    await page.waitForLoadState('networkidle');
  });

  test('should expand sidebar when collapse button is clicked', async ({ page }) => {
    // Find the sidebar collapse/expand button
    const toggleButton = page.getByRole('button', { name: /toggle sidebar|menu|collapse/i });

    // Verify sidebar is initially visible
    const sidebar = page.getByRole('navigation');
    await expect(sidebar).toBeVisible();

    // Get initial width or check for collapsed state
    const initialState = await sidebar.evaluate(el => {
      return window.getComputedStyle(el).width;
    });

    // Click the toggle button to collapse
    await toggleButton.click();

    // Wait for animation to complete
    await page.waitForTimeout(300);

    // Verify sidebar is collapsed (width reduced or hidden)
    const collapsedState = await sidebar.evaluate(el => {
      return window.getComputedStyle(el).width;
    });

    expect(collapsedState).not.toBe(initialState);
  });

  test('should collapse sidebar when toggle button is clicked', async ({ page }) => {
    const toggleButton = page.getByRole('button', { name: /toggle sidebar|menu|collapse/i });
    const sidebar = page.getByRole('navigation');

    // Click to collapse
    await toggleButton.click();
    await page.waitForTimeout(300);

    const collapsedWidth = await sidebar.evaluate(el => {
      return window.getComputedStyle(el).width;
    });

    // Click again to expand
    await toggleButton.click();
    await page.waitForTimeout(300);

    const expandedWidth = await sidebar.evaluate(el => {
      return window.getComputedStyle(el).width;
    });

    // Verify states are different
    expect(expandedWidth).not.toBe(collapsedWidth);
  });

  test('should maintain sidebar state and allow multiple toggles', async ({ page }) => {
    const toggleButton = page.getByRole('button', { name: /toggle sidebar|menu|collapse/i });
    const sidebar = page.getByRole('navigation');

    // Get initial state
    const initialWidth = await sidebar.evaluate(el => {
      return window.getComputedStyle(el).width;
    });

    // Toggle multiple times
    for (let i = 0; i < 3; i++) {
      await toggleButton.click();
      await page.waitForTimeout(300);
    }

    // After odd number of toggles, should return to initial state
    const finalWidth = await sidebar.evaluate(el => {
      return window.getComputedStyle(el).width;
    });

    expect(finalWidth).toBe(initialWidth);
  });

  test('should hide sidebar content when collapsed', async ({ page }) => {
    const toggleButton = page.getByRole('button', { name: /toggle sidebar|menu|collapse/i });
    const sidebarLinks = page.getByRole('link').filter({ has: page.locator('nav') });

    // Verify links are visible initially
    const firstLink = sidebarLinks.first();
    await expect(firstLink).toBeVisible();

    // Collapse sidebar
    await toggleButton.click();
    await page.waitForTimeout(300);

    // Check if content is hidden or has reduced opacity
    const isHidden = await firstLink.evaluate(el => {
      const style = window.getComputedStyle(el);
      return style.display === 'none' || style.visibility === 'hidden' || style.opacity === '0';
    });

    expect(isHidden).toBeTruthy();
  });

  test('should apply correct CSS classes during collapse/expand animation', async ({ page }) => {
    const toggleButton = page.getByRole('button', { name: /toggle sidebar|menu|collapse/i });
    const sidebar = page.getByRole('navigation');

    // Check initial class
    const initialClasses = await sidebar.evaluate(el => el.className);
    expect(initialClasses).toBeTruthy();

    // Click to toggle
    await toggleButton.click();

    // Check if class changes during animation
    const classesAfterToggle = await sidebar.evaluate(el => el.className);

    // Verify that either the class changed or the element has animation applied
    const hasAnimationOrClassChange = initialClasses !== classesAfterToggle || 
      await sidebar.evaluate(el => {
        const style = window.getComputedStyle(el);
        return style.transition !== 'none' || style.animation !== 'none';
      });

    expect(hasAnimationOrClassChange).toBeTruthy();
  });

  test('should be keyboard accessible for sidebar toggle', async ({ page }) => {
    const toggleButton = page.getByRole('button', { name: /toggle sidebar|menu|collapse/i });
    const sidebar = page.getByRole('navigation');

    // Get initial width
    const initialWidth = await sidebar.evaluate(el => {
      return window.getComputedStyle(el).width;
    });

    // Focus and press Enter
    await toggleButton.focus();
    await page.keyboard.press('Enter');
    await page.waitForTimeout(300);

    // Verify state changed
    const newWidth = await sidebar.evaluate(el => {
      return window.getComputedStyle(el).width;
    });

    expect(newWidth).not.toBe(initialWidth);
  });
});
